const info = phi.js(() => {
  const secs = [...document.querySelectorAll('button, [role="button"]')].filter(b => (b.textContent||'').trim() === 'Size');
  const b = secs[0];
  if (!b) return 'no size button';
  const panel = b.closest('div');
  // walk up to find container holding size labels
  let root = b.parentElement;
  for (let i=0;i<5 && root;i++){ if (/XXS[\s\S]*3XL/.test(root.textContent||'')) break; root = root.parentElement; }
  const inputs = [...root.querySelectorAll('input')].map(i => ({type:i.type, value:i.value, id:i.id, name:i.name, checked:i.checked, aria:(i.getAttribute('aria-label')||'')}));
  const labels = [...root.querySelectorAll('label')].map(l => (l.textContent||'').trim()).slice(0,20);
  const other = [...root.querySelectorAll('button,[role="checkbox"],[role="option"]')].map(e => e.tagName+':'+(e.textContent||'').trim().slice(0,20)+':'+(e.getAttribute('role')||'')+':'+(e.getAttribute('aria-checked')||'')).slice(0,30);
  return { inputs, labels, other };
});
return info;

