const d = phi.js(() => {
  const acc = document.getElementById('accordion-size');
  const r = acc.getBoundingClientRect();
  const cx = r.left + r.width/2, cy = r.top + r.height/2;
  const top = document.elementFromPoint(cx, cy);
  const cs = getComputedStyle(acc);
  const parent = acc.parentElement;
  return {
    rect: {x: Math.round(r.x), y: Math.round(r.y), w: Math.round(r.width), h: Math.round(r.height)},
    pointerEvents: cs.pointerEvents, display: cs.display, visibility: cs.visibility,
    topEl: top ? {tag: top.tagName, cls: (top.className||'').toString().slice(0,80), id: top.id, txt: (top.innerText||'').trim().slice(0,20)} : null,
    accIsTopOrParent: top ? (acc === top || acc.contains(top)) : false,
    parentCls: (parent.className||'').toString(),
    scrollY: window.scrollY,
    viewportH: window.innerHeight,
    allAccordions: [...document.querySelectorAll('.accordion__label-wrapper')].map(n => ({id: n.id, expanded: n.getAttribute('aria-expanded'), txt: (n.innerText||'').trim()}))
  };
});
return d;

const env = phi.js(() => ({ iw: window.innerWidth, ih: window.innerHeight, dpr: window.devicePixelRatio, sx: window.scrollX }));
const obs = phi.observe({ maxElements: 200 });
const lines = obs.nodes.map(n => `${n.ref}. ${n.role} "${n.text}"`.slice(0, 90));
const sizeNode = obs.nodes.find(n => /^size$/i.test((n.text || '').trim()));
let clicked = null;
if (sizeNode) { clicked = phi.click(sizeNode.ref); }
const after = phi.js(() => {
  const acc = document.getElementById('accordion-size');
  const c = document.getElementById('accordion-size-content');
  return { expanded: acc && acc.getAttribute('aria-expanded'), h: c ? Math.round(c.getBoundingClientRect().height) : null, visibleInputs: [...document.querySelectorAll('#sizeFilter input')].filter(i => i.getClientRects().length).length };
});
return { env, sizeNode, clicked, after, lines: lines.slice(0, 120) };

const pre = phi.js(() => {
  const acc = document.getElementById('accordion-size');
  if (!acc) return { acc: null };
  const out = { accRect: (r => ({x: Math.round(r.x), y: Math.round(r.y), w: Math.round(r.width)}))(acc.getBoundingClientRect()), docW: document.documentElement.scrollWidth, winW: window.innerWidth, scrollers: [] };
  let n = acc.parentElement;
  while (n && n !== document.documentElement) {
    const cs = getComputedStyle(n);
    if (n.scrollWidth > n.clientWidth + 5 || cs.overflowX !== 'visible') {
      out.scrollers.push({ tag: n.tagName, cls: (n.className||'').toString().slice(0,70), overflowX: cs.overflowX, sw: n.scrollWidth, cw: n.clientWidth, sl: n.scrollLeft });
    }
    n = n.parentElement;
  }
  return out;
});

let clickRes = null, err = null;
try { clickRes = phi.click('#accordion-size'); } catch (e) { err = String(e).slice(0, 200); }

const post = phi.js(() => {
  const acc = document.getElementById('accordion-size');
  const c = document.getElementById('accordion-size-content');
  return {
    expanded: acc && acc.getAttribute('aria-expanded'),
    contentH: c ? Math.round(c.getBoundingClientRect().height) : null,
    contentVisible: c ? !!(c.getClientRects().length) : null,
    scrollX: window.scrollX
  };
});
return { pre, clickRes, err, post };
